
docker rm -f lute-upgrade 2>$null; docker run --name lute-upgrade --workdir /opt --entrypoint /bin/sh unveilr-sandbox:latest -c 'set -e; sed -i s#luau-lang/lute@0.1.0-nightly.20260205#luau-lang/lute@1.0.0# /opt/rokit.toml; rokit update luau-lang/lute; LUTE_BIN=$(find /opt/.rokit/tool-storage/luau-lang/lute -type f -name lute | head -n 1); test -n "$LUTE_BIN"; ln -sf "$LUTE_BIN" /usr/local/bin/lute; /usr/local/bin/lute --version'; if ($LASTEXITCODE -eq 0) { docker commit lute-upgrade unveilr-sandbox:lute-1.0.0; docker rm lute-upgrade; docker run --rm --entrypoint /usr/local/bin/lute unveilr-sandbox:lute-1.0.0 --version }